package pendingaccounts

import (
	"bytes"
	"context"
	"crypto/ed25519"
	"encoding/hex"
	"encoding/json"
	"errors"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
)

const (
	reviewedState = "ownership-reviewed"
	reviewLifetime = 10 * time.Minute
	reviewDomain = "shadowops-identity-ownership-review-v1\n"
)

// ReviewStatement binds an external, manually conducted ownership review to
// exactly one pending account. An issue URL or digest alone does NOT prove
// ownership. Both signatures must be generated by independently authorized,
// offline reviewers after examining evidence outside GitHub and this repo.
type ReviewStatement struct {
	Environment string `json:"environment"`
	Subject string `json:"subject"`
	Source string `json:"source"`
	LegacyUsername string `json:"legacy_username"`
	ReviewRef string `json:"review_ref"`
	EvidenceSHA256 string `json:"evidence_sha256"`
	Nonce string `json:"nonce"`
	ReviewedAt int64 `json:"reviewed_at"`
	ValidUntil int64 `json:"valid_until"`
}

type SignedReview struct {
	Statement ReviewStatement
	SignatureA []byte
	SignatureB []byte
}

// NewReviewStore installs two independently provisioned, pinned public keys.
// New(ctx, db) remains reservation-only and can NEVER approve ownership.
// Callers must not accept review keys from requests, GitHub issues or plans.
func NewReviewStore(ctx context.Context, db *mongo.Database, a, b ed25519.PublicKey) (*Store, error) {
	if len(a) != ed25519.PublicKeySize || len(b) != ed25519.PublicKeySize || bytes.Equal(a, b) {
		return nil, ErrInvalid
	}
	s, err := New(ctx, db)
	if err != nil {
		return nil, err
	}
	s.reviewerA = append(ed25519.PublicKey(nil), a...)
	s.reviewerB = append(ed25519.PublicKey(nil), b...)
	return s, nil
}

func canonicalLowerHex(value string, bytesExpected int) bool {
	if len(value) != 2*bytesExpected {
		return false
	}
	raw, err := hex.DecodeString(value)
	return err == nil && len(raw) == bytesExpected && hex.EncodeToString(raw) == value
}

// VerifyReview is a narrow crypto/evidence-metadata check, not an assertion
// that a human actually owns the source account. A separate review process
// must verify ownership and protect its signing keys.
func VerifyReview(r SignedReview, reviewerA, reviewerB ed25519.PublicKey, now time.Time) error {
	v := r.Statement
	_, valid := validReservation(Reservation{
		Subject: v.Subject, Source: v.Source, LegacyUsername: v.LegacyUsername, ReviewRef: v.ReviewRef,
	})
	if !valid || v.Environment != "staging" || now.IsZero() ||
		!canonicalLowerHex(v.EvidenceSHA256, 32) || !canonicalLowerHex(v.Nonce, 16) ||
		v.ReviewedAt <= 0 || v.ValidUntil <= v.ReviewedAt ||
		v.ValidUntil-v.ReviewedAt > int64(reviewLifetime.Seconds()) ||
		now.Unix() < v.ReviewedAt-30 || now.Unix() >= v.ValidUntil ||
		len(reviewerA) != ed25519.PublicKeySize || len(reviewerB) != ed25519.PublicKeySize ||
		bytes.Equal(reviewerA, reviewerB) ||
		len(r.SignatureA) != ed25519.SignatureSize || len(r.SignatureB) != ed25519.SignatureSize {
		return ErrInvalid
	}
	payload, err := json.Marshal(v) // fixed struct field order, no map reordering
	if err != nil {
		return ErrInvalid
	}
	message := append([]byte(reviewDomain), payload...)
	if !ed25519.Verify(reviewerA, message, r.SignatureA) ||
		!ed25519.Verify(reviewerB, message, r.SignatureB) {
		return ErrInvalid
	}
	return nil
}

// ReviewPending is the ONLY state transition in this package. It is atomic
// and one-way: pending-review -> ownership-reviewed, never -> active.
// No password hashes, user sessions, product grants or credentials are added.
// A duplicate or mismatched attestation cannot overwrite another review.
func (s *Store) ReviewPending(ctx context.Context, signed SignedReview) error {
	if s == nil || s.accounts == nil || ctx == nil || ctx.Err() != nil {
		return ErrInvalid
	}
	if err := VerifyReview(signed, s.reviewerA, s.reviewerB, time.Now().UTC()); err != nil {
		return err
	}
	v := signed.Statement
	key, ok := normalizedUsername(v.LegacyUsername)
	if !ok {
		return ErrInvalid
	}
	filter := bson.D{
		{Key: "_id", Value: v.Subject},
		{Key: "environment", Value: "staging"},
		{Key: "state", Value: pendingState},
		{Key: "source", Value: v.Source},
		{Key: "legacy_username", Value: v.LegacyUsername},
		{Key: "alias_key", Value: key},
		{Key: "review_ref", Value: v.ReviewRef},
	}
	update := bson.D{{Key: "$set", Value: bson.D{
		{Key: "state", Value: reviewedState},
		{Key: "reviewed_at", Value: time.Unix(v.ReviewedAt, 0).UTC()},
		{Key: "evidence_sha256", Value: v.EvidenceSHA256},
		{Key: "review_nonce", Value: v.Nonce},
	}}}
	result, err := s.accounts.UpdateOne(ctx, filter, update)
	if err != nil {
		return err
	}
	if result.ModifiedCount != 1 {
		return ErrConflict
	}
	return nil
}

// IsReviewed only reports review metadata. It is deliberately NOT a login
// predicate, not a user account record and not an authorization capability.
func (s *Store) IsReviewed(ctx context.Context, subject string) (bool, error) {
	if s == nil || s.accounts == nil || ctx == nil || ctx.Err() != nil || !subjectRe.MatchString(subject) {
		return false, ErrInvalid
	}
	count, err := s.accounts.CountDocuments(ctx, bson.D{
		{Key: "_id", Value: subject},
		{Key: "environment", Value: "staging"},
		{Key: "state", Value: reviewedState},
	})
	if err != nil {
		return false, err
	}
	if count > 1 {
		return false, errors.New("duplicate reviewed identity record")
	}
	return count == 1, nil
}
